<div class="container storefront"><section class="catalog-heading"><span class="eyebrow">BỘ SƯU TẬP</span><h1>Sản phẩm</h1><p>Tìm kiếm, lọc và sắp xếp để chọn món đồ phù hợp nhất.</p></section><form class="catalog-filter" action="<?= BASE_URL ?>" method="get"><input type="hidden" name="action" value="products"><input name="keyword" value="<?= e($filters['keyword']) ?>" placeholder="Tìm tên sản phẩm…"><select name="category"><option value="">Tất cả danh mục</option><?php foreach ($categories as $category): ?><option value="<?= e($category['id']) ?>" <?= (int) $filters['danh_muc_id'] === (int) $category['id'] ? 'selected' : '' ?>><?= e($category['name']) ?></option><?php endforeach; ?></select><input name="min_price" type="number" min="0" value="<?= e($filters['min_price']) ?>" placeholder="Giá từ"><input name="max_price" type="number" min="0" value="<?= e($filters['max_price']) ?>" placeholder="Giá đến"><select name="sort"><option value="">Mới nhất</option><option value="rating" <?= $filters['sort'] === 'rating' ? 'selected' : '' ?>>Đánh giá cao</option><option value="price_asc" <?= $filters['sort'] === 'price_asc' ? 'selected' : '' ?>>Giá tăng dần</option><option value="price_desc" <?= $filters['sort'] === 'price_desc' ? 'selected' : '' ?>>Giá giảm dần</option></select><button class="button primary">Lọc sản phẩm</button></form><div class="product-grid"><?php if ($products): foreach ($products as $product) { require __DIR__ . '/partials/product_card.php'; } else: ?><p class="empty">Không tìm thấy sản phẩm phù hợp.</p><?php endif; ?></div></div>
